pub fn init_exercises_dir(&self, exercise_infos: &[ExerciseInfo]) -> Result<()> {
    create_dir("exercises").context("Failed to create the directory `exercises`")?;

    fs::write(
        "exercises/README.md",
        include_bytes!("../exercises/README.md"),
